559	    listDocs();
560	    return;
561	  }
562	  if (options.clean) {
563	    cleanDocs();
564	    return;
565	  }
566	  const exportOnly =
567	    options.exportPdf &&
568	    !options.scan &&
569	    !options.ci &&
570	    !options.setup &&
571	    !options.listDocs &&
572	    !options.clean &&
