export function validateThresholds(thresholds, metricIds) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return { valid: true, errors: [] };
  }

  const errors = [];
  const validMetricIds = new Set(metricIds);

  Object.entries(thresholds).forEach(([metricId, minValue]) => {
    if (!validMetricIds.has(metricId)) {
      errors.push(`Unknown metric: ${metricId}. Valid metrics: ${Array.from(validMetricIds).join(', ')}`);
    } else if (typeof minValue !== 'number' || minValue < 0 || minValue > 1) {
      errors.push(`Invalid threshold for ${metricId}: must be a number between 0 and 1, got ${minValue}`);
    }
  });

  return { valid: errors.length === 0, errors };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = null,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const metricIds = evaluations.map((m) => m.id);
  const validation = validateThresholds(thresholds, metricIds);

  if (!validation.valid) {
    throw new Error(`Invalid thresholds: ${validation.errors.join('; ')}`);
  }

  let passed = true;
  const thresholdResults = [];

  if (thresholds && Object.keys(thresholds).length > 0) {
    Object.entries(thresholds).forEach(([metricId, min]) => {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score;
      const thresholdPassed = score !== null && score >= min;
      if (!thresholdPassed) {
        passed = false;
      }
      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed: thresholdPassed
      });
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults.length > 0) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

