function parseThresholds(thresholdStrings?: string[]): Record<string, number> | null {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const thresholds: Record<string, number> = {};
  for (const thresholdStr of thresholdStrings) {
    const parts = thresholdStr.split('=');
    if (parts.length !== 2) {
      throw new Error(`Malformed threshold: '${thresholdStr}'. Expected format: <metric>=<number>`);
    }
    const [metricId, valueStr] = parts;
    const value = Number.parseFloat(valueStr);
    if (Number.isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold for ${metricId}: '${valueStr}' is not a valid number between 0 and 1`);
    }
    thresholds[metricId] = value;
  }
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: Record<string, number> | null = null;
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error('Invalid threshold option.', {
      error: error instanceof Error ? error.message : String(error)
    });
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let report: any;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds
    });
  } catch (error) {
    log.error('Failed to generate report.', {
      error: error instanceof Error ? error.message : String(error)
    });
    process.exit(2);
  }

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && Object.keys(thresholds).length > 0) {
    const passed = report.passed;
    if (!passed) {
      const failedThresholds = report.thresholds
        .filter((t: any) => !t.passed)
        .map((t: any) => `${t.metric} (min: ${t.min}, score: ${t.score ?? 'n/a'})`)
        .join(', ');
      log.warn('Evaluation thresholds not met.', { failed: failedThresholds });
      process.exit(1);
    }
  }
}

