import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function validateThresholds(thresholds, metricIds) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return { valid: true, errors: [] };
  }

  const errors = [];
  const validMetricIds = new Set(metricIds);

  Object.entries(thresholds).forEach(([metricId, minValue]) => {
    if (!validMetricIds.has(metricId)) {
      errors.push(`Unknown metric: ${metricId}. Valid metrics: ${Array.from(validMetricIds).join(', ')}`);
    } else if (typeof minValue !== 'number' || minValue < 0 || minValue > 1) {
      errors.push(`Invalid threshold for ${metricId}: must be a number between 0 and 1, got ${minValue}`);
    }
  });

  return { valid: errors.length === 0, errors };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = null,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const metricIds = evaluations.map((m) => m.id);
  const validation = validateThresholds(thresholds, metricIds);

  if (!validation.valid) {
    throw new Error(`Invalid thresholds: ${validation.errors.join('; ')}`);
  }

  let passed = true;
  const thresholdResults = [];

  if (thresholds && Object.keys(thresholds).length > 0) {
    Object.entries(thresholds).forEach(([metricId, min]) => {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score;
      const thresholdPassed = score !== null && score >= min;
      if (!thresholdPassed) {
        passed = false;
      }
      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed: thresholdPassed
      });
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults.length > 0) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

