      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: [],
      references: []
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBe(false);
    const threshold = report.thresholds.find((t) => t.metric === 'exact_match');
    expect(threshold.score).toBe(null);
    expect(threshold.passed).toBe(false);
  });

  it('throws on unknown metric in thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { unknown_metric: 0.5 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });
    }).toThrow('Invalid thresholds');
  });

  it('throws on invalid threshold value', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 1.5 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });
    }).toThrow('Invalid thresholds');
  });
});

